package com.shahaabapps.core.content

/**
 * AZ-204 mock exam: 50 scenario questions across every module, timed like the
 * real sitting, with no feedback until the end. Pass at 70 percent, which is
 * the 700 of 1000 the real exam asks for.
 */
internal object Az204Mock {
    val quiz = Quiz(
        id = "az-mock", title = "AZ-204 mock exam", passPercent = 70, timeLimitMinutes = 100, instantFeedback = false, drawCount = 50,
        questions = B.spread(listOf(
            // Compute
            B.q("mk1", "az-app-service", "A web app must run Linux containers, keep running without cold starts and scale to several instances. Which hosting plan is the least expensive that meets this?", listOf("Free", "Shared", "Basic", "Isolated"), setOf(2), "Basic is the first tier with dedicated compute, Linux and manual scale out; Free and Shared cannot scale out.",
                scenario = "You are migrating the Two Tracks API to Azure App Service."),
            B.q("mk2", "az-app-service", "A Linux web app must receive its connection string as an environment variable without changing code. Where do you set it?", listOf("web.config", "Application settings in Configuration", "The Dockerfile", "A storage queue"), setOf(1), "App settings are injected as environment variables at start-up and override values in files."),
            B.q("mk3", "az-slots-scaling", "A new build must be tested on production hardware and go live without downtime, with instant rollback. What do you use?", listOf("Scale up the plan", "A deployment slot and swap", "A second App Service plan", "Autoscale"), setOf(1), "Slots warm the new build, swap it into production and swap back if needed."),
            B.q("mk4", "az-slots-scaling", "A setting must keep its value in the production slot after a swap. How do you mark it?", listOf("Deployment slot setting (sticky)", "Read-only", "Connection string type", "Hidden"), setOf(0), "Slot settings stay with the slot instead of travelling with the code."),
            B.q("mk5", "az-slots-scaling", "The App Service plan must add instances when CPU is above 70 percent for ten minutes and remove them at night. Which features? Select all that apply.", listOf("A metric-based autoscale rule", "A schedule-based autoscale profile", "Scale up to Premium", "A deployment slot"), setOf(0, 1), "Autoscale combines metric rules and schedule profiles; scaling up changes size, not count."),
            B.q("mk6", "az-functions", "A function must run every night at 02:00 and must never run two copies at once on the Consumption plan. Which trigger and what else?", listOf("Timer trigger; the singleton lock is built in", "HTTP trigger with a scheduler", "Queue trigger with one message", "Event Grid trigger"), setOf(0), "Timer triggers use a distributed lock so one instance runs per schedule."),
            B.q("mk7", "az-functions", "A function on the Consumption plan sometimes takes 12 minutes and fails. What is the cheapest fix?", listOf("Increase functionTimeout beyond 10 minutes on Consumption", "Move to the Premium or Dedicated plan", "Add more instances", "Use a Logic App"), setOf(1), "Consumption caps execution at 10 minutes; Premium and Dedicated allow longer or unlimited timeouts."),
            B.q("mk8", "az-functions", "Which binding writes a document to Cosmos DB from a queue-triggered function with no SDK code?", listOf("An input binding", "An output binding", "A trigger", "A Durable orchestration"), setOf(1), "Output bindings send data to a service declaratively."),
            B.q("mk9", "az-durable", "A workflow calls three functions in order, each needing the result of the previous, and must survive restarts. Which pattern?", listOf("Fan-out/fan-in", "Function chaining with a Durable orchestrator", "Async HTTP API", "Monitor"), setOf(1), "Chaining in an orchestrator checkpoints each step so the sequence resumes after a restart."),
            B.q("mk10", "az-durable", "Which Durable Functions component must be deterministic and must not call external services directly?", listOf("Client function", "Orchestrator function", "Activity function", "Entity function"), setOf(1), "Orchestrators are replayed; side effects belong in activities."),
            B.q("mk11", "az-containers", "A batch job container must run once, on demand, with no orchestration and the fewest moving parts. Which service?", listOf("Azure Kubernetes Service", "Azure Container Instances", "App Service", "Virtual machine scale set"), setOf(1), "ACI runs a container on demand with per-second billing and no cluster."),
            B.q("mk12", "az-containers", "Several containers must share a single lifecycle, local network and storage on ACI. What do you create?", listOf("A container group", "A pod", "A Dapr sidecar", "A registry task"), setOf(0), "A container group is ACI's equivalent of a pod."),
            B.q("mk13", "az-containers", "Images must be built in Azure from a Dockerfile in a Git repository without local Docker. Which feature?", listOf("ACR Tasks", "ACI restart policy", "Container Apps revisions", "Image pull secrets"), setOf(0), "ACR Tasks build and push images from source in the cloud."),
            // Storage
            B.q("mk14", "az-blob-basics", "Backups must survive the loss of a whole region and be readable from the secondary region at any time. Which redundancy?", listOf("LRS", "ZRS", "GRS", "RA-GRS"), setOf(3), "RA-GRS replicates to a paired region and allows reads from it."),
            B.q("mk15", "az-blob-basics", "Files are read often for a week, rarely for a year, then kept for seven years untouched. What is the cheapest compliant setup?", listOf("Hot forever", "Hot, lifecycle to Cool at 7 days, Archive at 365 days", "Archive from day one", "Cool forever"), setOf(1), "A lifecycle policy moves blobs down the tiers as access drops."),
            B.q("mk16", "az-blob-sdk", "A web client must upload directly to a private container for the next 15 minutes without the account key. What does the API return?", listOf("The connection string", "A user delegation SAS with Create and Write", "A lease id", "An index tag"), setOf(1), "A short SAS scoped to the container grants just that permission for that window."),
            B.q("mk17", "az-blob-sdk", "Blobs must be findable across the account by a department attribute. Which feature?", listOf("Metadata", "Blob index tags", "Snapshots", "Soft delete"), setOf(1), "Index tags are indexed and queryable across containers; metadata is not."),
            B.q("mk18", "az-cosmos-model", "A container stores orders; most queries are by customer id and customers are many. Which partition key?", listOf("/country", "/customerId", "/orderDate", "/status"), setOf(1), "Many distinct values and the common query stays in one partition."),
            B.q("mk19", "az-cosmos-model", "After a user updates their profile they must see the change immediately, while others may see it a little later. Which consistency?", listOf("Strong", "Session", "Eventual", "Bounded staleness"), setOf(1), "Session guarantees read-your-own-writes at low cost."),
            B.q("mk20", "az-cosmos-model", "Writes are spiky and mostly zero overnight; cost must track usage. Which capacity mode?", listOf("Provisioned at peak", "Serverless", "Dedicated gateway", "Multi-region writes"), setOf(1), "Serverless charges per request unit consumed."),
            B.q("mk21", "az-cosmos-sdk", "Every insert into a Cosmos container must update a materialised view within seconds. Which approach?", listOf("A timer function polling the container", "A Cosmos DB trigger reading the change feed", "A stored procedure", "A pre-trigger"), setOf(1), "The change feed delivers inserts and updates to a Function trigger near real time."),
            B.q("mk22", "az-cosmos-sdk", "Two writers may update the same document; the loser must get an error rather than overwrite. What do you use?", listOf("Strong consistency", "IfMatchEtag on ReplaceItem", "A larger RU budget", "TTL"), setOf(1), "ETag-based optimistic concurrency returns 412 on conflict."),
            // Security
            B.q("mk23", "az-identity", "A daemon with no user must call your API every hour. Which permission type and flow?", listOf("Delegated, authorization code", "Application, client credentials", "Delegated, device code", "Application, implicit"), setOf(1), "No signed-in user means application permissions obtained with client credentials."),
            B.q("mk24", "az-identity", "Your single-page app signs users in. Which flow should it use?", listOf("Implicit", "Authorization code with PKCE", "Client credentials", "Resource owner password"), setOf(1), "Auth code with PKCE is the recommended flow for public clients."),
            B.q("mk25", "az-identity", "An API receives a token. Which claim must it check to be sure the token was issued for it?", listOf("aud", "iss only", "name", "nonce"), setOf(0), "The audience must match the API's identifier."),
            B.q("mk26", "az-msal", "Users complain about frequent sign-in prompts in a desktop app using MSAL. What is the fix?", listOf("Use ReceiveAndDelete", "Call AcquireTokenSilent first and only fall back to interactive on MsalUiRequiredException", "Request /.default", "Disable the token cache"), setOf(1), "Silent acquisition uses the cache and refresh token; interactive is the fallback."),
            B.q("mk27", "az-msal", "A confidential client must get a token for its own identity. Which scope format is required?", listOf("api://tt/Logs.Read", "api://tt/.default", "openid profile", "offline_access"), setOf(1), "Client credentials use the /.default scope for the resource."),
            B.q("mk28", "az-graph", "You call /users with \$count=true and get an error. Which header is missing?", listOf("Prefer: return=minimal", "ConsistencyLevel: eventual", "Accept-Language", "If-None-Match"), setOf(1), "Advanced directory queries require ConsistencyLevel: eventual."),
            B.q("mk29", "az-graph", "A Graph response includes @odata.nextLink. What should your code do?", listOf("Ignore it", "Call it to fetch the next page", "Retry the original request", "Switch to beta"), setOf(1), "Results are paged; the nextLink URL returns the following page."),
            B.q("mk30", "az-keyvault", "An App Service must read a secret with no credential anywhere in code or settings. Which combination?", listOf("Connection string in app settings", "System-assigned managed identity plus Key Vault Secrets User role", "Client secret in Key Vault", "Shared access signature"), setOf(1), "The identity gets a token at runtime; the role allows reading secrets."),
            B.q("mk31", "az-keyvault", "Twenty function apps need identical vault access and the roles must exist before deployment. Which identity?", listOf("System-assigned on each app", "One user-assigned identity", "An app registration with a certificate", "An access policy per app"), setOf(1), "User-assigned identities are standalone, shareable and can be granted roles in advance."),
            B.q("mk32", "az-keyvault", "Cryptographic keys must be stored in hardware security modules. Which Key Vault tier?", listOf("Standard", "Premium", "Basic", "Developer"), setOf(1), "Premium provides HSM-backed keys."),
            B.q("mk33", "az-appconfig", "A feature must be shown to 20 percent of users first and to everyone later with no redeploy. Which service and feature?", listOf("Key Vault secret", "App Configuration feature flag with a percentage filter", "A deployment slot", "An APIM policy"), setOf(1), "Feature flags with filters are evaluated at runtime from App Configuration."),
            B.q("mk34", "az-appconfig", "All instances must pick up a changed setting within a minute with minimal polling. What do you register?", listOf("Every key", "A sentinel key with refreshAll", "A webhook per instance", "A Key Vault reference"), setOf(1), "One sentinel key is watched; its change triggers a full refresh."),
            // Monitor
            B.q("mk35", "az-appinsights", "You need to count completed checkouts per hour and split them by payment method in a chart. Which call?", listOf("TrackTrace", "TrackEvent with a property", "TrackDependency", "TrackPageView"), setOf(1), "Custom events with properties support counting and splitting in Logs and Metrics."),
            B.q("mk36", "az-appinsights", "Telemetry costs are too high. Counts must stay accurate. What do you configure?", listOf("Sampling", "A second resource", "Longer retention", "Live Metrics"), setOf(0), "Adaptive or fixed sampling reduces volume and corrects counts."),
            B.q("mk37", "az-appinsights", "Which KQL query returns failed requests grouped by name in the last hour?", listOf("requests | where success == false and timestamp > ago(1h) | summarize count() by name", "requests | project name", "exceptions | take 10", "traces | order by timestamp"), setOf(0), "where filters, summarize count() by groups."),
            B.q("mk38", "az-availability", "A health endpoint is only reachable inside a virtual network. How do you track its availability?", listOf("A standard availability test", "A Function inside the VNet calling TrackAvailability", "A URL ping test", "Smart detection"), setOf(1), "Standard tests probe from public locations and cannot reach private endpoints."),
            B.q("mk39", "az-availability", "Instances scale out and in every few minutes. Which two changes stop this? Select all that apply.", listOf("Add a cooldown", "Separate the scale-out and scale-in thresholds", "Remove the scale-in rule", "Scale up the tier"), setOf(0, 1), "Cooldown plus a threshold gap prevents flapping."),
            B.q("mk40", "az-redis", "The app opens a new Redis connection per request and runs out of sockets. What is the fix?", listOf("Use Basic tier", "Share one ConnectionMultiplexer", "Disable TLS", "Use HGETALL"), setOf(1), "The multiplexer is meant to be created once and shared."),
            B.q("mk41", "az-redis", "Cached data must persist to disk and the cache must live in a virtual network. Which tier?", listOf("Basic", "Standard", "Premium", "Any tier"), setOf(2), "Premium adds persistence, clustering and VNet injection."),
            B.q("mk42", "az-cdn", "Users still see an old stylesheet after a deployment through Azure Front Door. What is the quickest fix and the long-term fix? Select all that apply.", listOf("Purge the path now", "Use hashed file names for assets", "Disable HTTPS", "Set TTL to a year"), setOf(0, 1), "Purge evicts the cached copy; versioned names mean future deployments need no purge."),
            // Connect
            B.q("mk43", "az-apim", "Partners may call 100 times a minute and get HTTP 429 beyond that. Which policy?", listOf("quota-by-key", "rate-limit-by-key", "validate-jwt", "ip-filter"), setOf(1), "rate-limit controls short windows and returns 429."),
            B.q("mk44", "az-apim", "Each subscription is limited to one million calls a month. Which policy?", listOf("rate-limit", "quota", "cache-lookup", "cors"), setOf(1), "quota is the long-term allowance and returns 403 when exceeded."),
            B.q("mk45", "az-apim", "A back end requires a client certificate. Which APIM policy supplies it?", listOf("authentication-basic", "authentication-certificate", "validate-jwt", "set-header"), setOf(1), "authentication-certificate presents a client certificate to the back end."),
            B.q("mk46", "az-eventgrid", "A function must run only when a .pdf is uploaded to the invoices container. How do you achieve this with the least processing?", listOf("Filter in the function code", "Subject begins-with /blobServices/default/containers/invoices and ends-with .pdf on the subscription", "A consumer group", "Capture"), setOf(1), "Subject filters on the Event Grid subscription prevent irrelevant deliveries."),
            B.q("mk47", "az-eventgrid", "Your webhook endpoint receives no events after creating the subscription. What did it most likely fail to do?", listOf("Return 202", "Complete the validation handshake", "Use port 8080", "Set a TTL"), setOf(1), "Event Grid delivers only after the endpoint echoes the validation code or the URL is visited."),
            B.q("mk48", "az-eventhubs", "Telemetry from thousands of devices must be ingested at high throughput, retained for a week and read independently by two teams. Which service and feature?", listOf("Service Bus queue", "Event Hubs with two consumer groups", "Storage queue", "Event Grid custom topic"), setOf(1), "Event Hubs retains streams; consumer groups give independent readers."),
            B.q("mk49", "az-servicebus", "Orders for the same customer must be processed in order by one consumer at a time, and poison messages must be set aside after five tries. Which features? Select all that apply.", listOf("Sessions", "Max delivery count of 5 with dead-lettering", "ReceiveAndDelete mode", "Duplicate detection"), setOf(0, 1), "Sessions give per-key ordering; max delivery count routes failures to the dead-letter queue."),
            B.q("mk50", "az-servicebus", "A queue must exceed 80 GB and keep a server-side log of every operation. Which service?", listOf("Service Bus Standard", "Service Bus Premium", "Azure Queue Storage", "Event Hubs"), setOf(2), "Storage queues scale to the account limit and support storage analytics logging."),
        ) + Az204Mock2.questions),
    )
}
